function watchTimes(lit: number): string[] {
  const bits = (x: number) => { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; };
  const out: string[] = [];
  for (let h = 0; h < 12; h++)
    for (let m = 0; m < 60; m++)
      if (bits(h) + bits(m) === lit) out.push(h + ":" + String(m).padStart(2, "0"));
  return out;
}

