function watchTimes(lit: number): string[] {
  // lights 0-3 are hour bits 8,4,2,1; lights 4-9 are minute bits 32..1
  const VALUES = [8, 4, 2, 1, 32, 16, 8, 4, 2, 1];
  const out: string[] = [];
  const go = (i: number, left: number, h: number, m: number) => {
    if (h > 11 || m > 59) return;
    if (left === 0) { out.push(h + ":" + String(m).padStart(2, "0")); return; }
    if (10 - i < left) return; // not enough lights left
    if (i < 4) go(i + 1, left - 1, h + VALUES[i], m);
    else go(i + 1, left - 1, h, m + VALUES[i]);
    go(i + 1, left, h, m);
  };
  go(0, lit, 0, 0);
  return out;
}

