      out.push(h + ":" + String(m).padStart(2, "0"));
      return;
    }
    if (10 - i < left) return;
    if (i < 4) go(i + 1, left - 1, h + VALUES[i], m);
    else go(i + 1, left - 1, h, m + VALUES[i]);
    go(i + 1, left, h, m);
  };
  go(0, lit, 0, 0);
  return out;
}
